"""Prove structural recipes from generated bytes, probe outcomes and decoded output."""

from __future__ import annotations

import hashlib
import json
import re
import shutil
from pathlib import Path

import pytest
from ruamel.yaml import YAML
from typer.testing import CliRunner

from chaos_librarian.cli.app import app
from chaos_librarian.contract import SCENARIO_SCHEMA_VERSION
from chaos_librarian.materializer.tooling._subprocess import RecordedToolResult, run_recorded_tool

pytestmark = pytest.mark.skipif(
    any(shutil.which(tool) is None for tool in ("ffmpeg", "ffprobe", "mkvinfo")),
    reason="structural real-tool tests require ffmpeg, ffprobe and mkvinfo",
)
_RUNNER = CliRunner()
_FIXTURES = Path(__file__).parents[1] / "fixtures" / "scenarios"


def _scenario(
    tmp_path: Path, container: str, *, damaged: bool, placement: str | None = None
) -> Path:
    yaml = YAML(typ="safe")
    source = "audio-only-track.yaml" if container == "mp3" else "malformed-container-header.yaml"
    raw = yaml.load((_FIXTURES / source).read_text())
    raw["schema_version"] = SCENARIO_SCHEMA_VERSION
    raw["profiles"] = ["malformed-media"]
    if container == "mp3":
        asset = raw["artists"][0]["albums"][0]["discs"][0]["tracks"][0]["variants"][0]["bundle"][
            "assets"
        ][0]
        asset["audio"][0].update(codec="mp3", sample_rate=44100)
    else:
        asset = raw["movies"][0]["variants"][0]["bundle"]["assets"][0]
        asset["video"]["resolution"] = "sd"
        if placement is not None:
            asset["mp4_moov_placement"] = placement
    asset["container"] = container
    asset["duration_seconds"] = 2
    event = {"id": "structural", "at": "1ms", "target": asset["id"]}
    if container == "mp3":
        event.update(action="truncate_file", boundary="mp3_after_16_frames")
    else:
        event.update(
            action="corrupt_container_header",
            region=f"{container}_{'moov' if container == 'mp4' else 'cues'}",
        )
    raw["timeline"] = [event] if damaged else []
    path = tmp_path / ("damaged.yaml" if damaged else "healthy.yaml")
    with path.open("w") as file:
        yaml.dump(raw, file)
    return path


def _tool(argv: list[str]) -> RecordedToolResult:
    result = run_recorded_tool(
        argv,
        tool=argv[0],
        version="test",
        timeout_s=15,
        stdout_mode="pipe",
        text=False,
        max_output_bytes=1024 * 1024,
    )
    assert result.failure_kind is None, result.stderr_tail
    return result


def _materialize(scenario: Path, out: Path, *, run: bool = False) -> tuple[Path, dict]:
    argv = ["run" if run else "materialize", str(scenario), "--out", str(out), "--json"]
    if run:
        argv.extend(["--duration", "2ms", "--speed", "1000x"])
    result = _RUNNER.invoke(app, argv)
    assert result.exit_code == 0, result.stdout + result.stderr
    report = json.loads((out / "materialization.json").read_text())
    assert report["outcome"] == "success"
    return out / report["materialized"][0]["location_path"], report


def _mp4_moov_type(data: bytes) -> int:
    offset = 0
    while offset < len(data):
        size = int.from_bytes(data[offset : offset + 4], "big")
        assert size >= 8
        if data[offset + 4 : offset + 8] == b"moov":
            return offset + 4
        offset += size
    pytest.fail("healthy control has no moov")


def _packets(path: Path) -> list[dict]:
    result = _tool(
        [
            "ffprobe",
            "-v",
            "error",
            "-select_streams",
            "a:0",
            "-show_packets",
            "-show_entries",
            "packet=pos,size",
            "-of",
            "json",
            str(path),
        ]
    )
    assert result.invocation.exit_code == 0, result.stderr_tail
    return json.loads(result.stdout_text())["packets"]


@pytest.mark.parametrize(
    ("container", "placement"),
    [("mp4", "moov_at_start"), ("mp4", "moov_at_end"), ("mkv", None), ("mp3", None)],
)
def test_structural_recipe_bytes_probe_decode_and_replay(
    tmp_path: Path, container: str, placement: str | None
) -> None:
    healthy, _ = _materialize(
        _scenario(tmp_path, container, damaged=False, placement=placement), tmp_path / "healthy"
    )
    scenario = _scenario(tmp_path, container, damaged=True, placement=placement)
    damaged, report = _materialize(scenario, tmp_path / "damaged", run=True)
    original, output = healthy.read_bytes(), damaged.read_bytes()
    action = report["corruption_actions"][0]
    assert action["input_content_hash"] == "sha256:" + hashlib.sha256(original).hexdigest()
    assert action["output_content_hash"] == "sha256:" + hashlib.sha256(output).hexdigest()
    assert original != output
    probe = _tool(["ffprobe", "-v", "error", "-show_format", "-of", "json", str(damaged)])
    healthy_decode = _tool(["ffmpeg", "-v", "error", "-i", str(healthy), "-f", "framemd5", "-"])
    assert healthy_decode.invocation.exit_code == 0, healthy_decode.stderr_tail
    if container == "mp4":
        offset = _mp4_moov_type(original)
        assert output == original[:offset] + bytes(4) + original[offset + 4 :]
        assert (action["byte_start"], action["byte_count"]) == (offset, 4)
        assert probe.invocation.exit_code != 0
        assert action["probe_outcome"] == "failed_expected"
    elif container == "mkv":
        info = _tool(["mkvinfo", "--ui-language", "en_US", "--all", "--positions", str(healthy)])
        assert info.invocation.exit_code == 0, info.stderr_tail
        match = re.search(r"\+ Cues at (\d+)", info.stdout_text())
        assert match is not None, info.stdout_text()
        offset = int(match[1])
        assert original[offset : offset + 4] == bytes.fromhex("1c53bb6b")
        assert output == original[:offset] + bytes(4) + original[offset + 4 :]
        assert (action["byte_start"], action["byte_count"]) == (offset, 4)
        decoded = _tool(["ffmpeg", "-v", "error", "-i", str(damaged), "-f", "framemd5", "-"])
        assert decoded.invocation.exit_code == 0, decoded.stderr_tail
        assert decoded.stdout == healthy_decode.stdout
    else:
        packets = _packets(healthy)
        offset = int(packets[15]["pos"]) + int(packets[15]["size"])
        assert output == original[:offset]
        assert (action["byte_start"], action["byte_count"]) == (offset, len(original) - offset)
        assert len(_packets(damaged)) == 16
        assert len(packets) > 16
        pcm = [
            _tool(["ffmpeg", "-v", "error", "-i", str(path), "-f", "s16le", "-"])
            for path in (healthy, damaged)
        ]
        assert all(result.invocation.exit_code == 0 for result in pcm)
        assert isinstance(pcm[0].stdout, bytes)
        assert isinstance(pcm[1].stdout, bytes)
        assert 0 < len(pcm[1].stdout) < len(pcm[0].stdout)
    if container != "mp4":
        assert probe.invocation.exit_code == 0, probe.stderr_tail
        assert action["probe_outcome"] == "still_probeable"
    replay = _RUNNER.invoke(
        app,
        [
            "replay",
            str(tmp_path / "damaged" / "replay.json"),
            "--out",
            str(tmp_path / "replay"),
            "--against",
            str(tmp_path / "damaged"),
            "--json",
        ],
    )
    assert replay.exit_code == 0, replay.stdout + replay.stderr


def test_unsupported_structural_duration_rejected_before_run_creation(tmp_path: Path) -> None:
    scenario = _scenario(tmp_path, "mp4", damaged=True)
    scenario.write_text(scenario.read_text().replace("duration_seconds: 2", "duration_seconds: 31"))
    out = tmp_path / "unsupported"
    result = _RUNNER.invoke(app, ["materialize", str(scenario), "--out", str(out), "--json"])
    assert result.exit_code != 0
    assert "E_MATERIALIZE_UNSUPPORTED" in result.stdout + result.stderr
    assert not out.exists()
